left: 2px solid transparent;\n  padding: 4px 20px;\n  font-size: 13px;\n  font-weight: 400;\n}\n\n/* nested links */\n.docs-sidebar .nav .nav>li>a {\n  padding-top: 1px;\n  padding-bottom: 1px;\n  padding-left: 30px;\n  font-size: 12px;\n}\n\n/* active & hover links */\n.docs-sidebar .nav>.active>a,\n.docs-sidebar .nav>li>a:hover,\n.docs-sidebar .nav>li>a:focus {\n  color: #563d7c;\n  text-decoration: none;\n  background-color: transparent;\n  border-left-color: #563d7c;\n}\n/* all active links */\n.docs-sidebar .nav>.active>a,\n.docs-sidebar .nav>.active:hover>a,\n.docs-sidebar .nav>.active:focus>a {\n  font-weight: 700;\n}\n/* nested active links */\n.docs-sidebar .nav .nav>.active>a,\n.docs-sidebar .nav .nav>.active:hover>a,\n.docs-sidebar .nav .nav>.active:focus>a {\n  font-weight: 500;\n}\n\n/* hide inactive nested list */\n.docs-sidebar .nav ul.nav {\n  display: none;\n}\n/* show active nested list */\n.docs-sidebar .nav>.active>ul.nav {\n  display: block;\n}\n\n//media queries\n//\n////collapse the navbar if the screen is below a certain size\n//@media screen and (max-width: 500px){\n//  .docs-sidebar {\n//    display:none\n//  }\n//}\n","//TODO make blockquote text smaller\n.example {\n  font-size: smaller;\n}"],"sourceRoot":"/source/"}
